-- Initial source-labelled subject catalogue for PRIME-CBT External Exams.
-- This seeds subject names only. It does not claim to contain any full syllabus or topic outline.
-- JAMB: official 2026 UTME Training Manual. WAEC: official 2026/2027 FAQ subject options.
-- NECO: official 2025 SSCE External registration guideline (dated list; verify current session).
begin;
on conflict (exam_code,slug) do update set
  name=excluded.name,
  syllabus_version=excluded.syllabus_version,
  is_active=true,
  sort_order=excluded.sort_order;
commit;
